    { const char * tb_v3296 = "// ---------- картинки PNG (load_image) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3296; }
    { const char * tb_v3297 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v3297; }
    { const char * tb_v3298 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v3298; }
    { const char * tb_v3299 = "typedef struct { const unsigned char *p, *end; unsigned bits; int nb, err; unsigned char *out; size_t n, cap; } tb_zs;\n"; *(const char * *)tb_grow(v_lines) = tb_v3299; }
    { const char * tb_v3300 = "typedef struct { short count[16], sym[320]; } tb_huff;\n"; *(const char * *)tb_grow(v_lines) = tb_v3300; }
    { const char * tb_v3301 = "TB_API unsigned tb_zbits(tb_zs *z, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3301; }
    { const char * tb_v3302 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3302; }
    { const char * tb_v3303 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3303; }
    { const char * tb_v3304 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v3304; }
    { const char * tb_v3305 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3305; }
    { const char * tb_v3306 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3306; }
    { const char * tb_v3307 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3307; }
    { const char * tb_v3308 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3308; }
    { const char * tb_v3309 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3309; }
    { const char * tb_v3310 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3310; }
    { const char * tb_v3311 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3311; }
    { const char * tb_v3312 = "        size_t nc = z->cap ? z->cap * 2 : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v3312; }
    { const char * tb_v3313 = "        unsigned char *q = realloc(z->out, nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v3313; }
    { const char * tb_v3314 = "        if (!q) { z->err = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3314; }
    { const char * tb_v3315 = "        z->out = q; z->cap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v3315; }
    { const char * tb_v3316 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3316; }
    { const char * tb_v3317 = "    z->out[z->n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3317; }
    { const char * tb_v3318 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3318; }
    { const char * tb_v3319 = "TB_API void tb_hbuild(tb_huff *h, const unsigned char *len, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3319; }
    { const char * tb_v3320 = "    short offs[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v3320; }
    { const char * tb_v3321 = "    memset(h->count, 0, sizeof h->count);\n"; *(const char * *)tb_grow(v_lines) = tb_v3321; }
    { const char * tb_v3322 = "    for (int i = 0; i < n; i++) h->count[len[i]]++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3322; }
    { const char * tb_v3323 = "    h->count[0] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3323; }
    { const char * tb_v3324 = "    offs[1] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3324; }
    { const char * tb_v3325 = "    for (int l = 1; l < 15; l++) offs[l + 1] = offs[l] + h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v3325; }
    { const char * tb_v3326 = "    for (int i = 0; i < n; i++) if (len[i]) h->sym[offs[len[i]]++] = (short)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v3326; }
    { const char * tb_v3327 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3327; }
    { const char * tb_v3328 = "TB_API int tb_hdec(tb_zs *z, const tb_huff *h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3328; }
    { const char * tb_v3329 = "    int code = 0, first = 0, index = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3329; }
    { const char * tb_v3330 = "    for (int l = 1; l < 16; l++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3330; }
    { const char * tb_v3331 = "        code |= (int)tb_zbits(z, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3331; }
