    { const char * tb_v4959 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4959; }
    { const char * tb_v4960 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4960; }
