    { const char * tb_v4984 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4984; }
    { const char * tb_v4985 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v4985; }
    { const char * tb_v4986 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4986; }
    { const char * tb_v4987 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4987; }
    { const char * tb_v4988 = "    tb_gfx_events();\n"; *(const char * *)tb_grow(v_lines) = tb_v4988; }
    { const char * tb_v4989 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v4989; }
    { const char * tb_v4990 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v4990; }
    { const char * tb_v4991 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4991; }
    { const char * tb_v4992 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4992; }
    { const char * tb_v4993 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4993; }
    { const char * tb_v4994 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v4994; }
    { const char * tb_v4995 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4995; }
    { const char * tb_v4996 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v4996; }
    { const char * tb_v4997 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v4997; }
    { const char * tb_v4998 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v4998; }
    { const char * tb_v4999 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v4999; }
    { const char * tb_v5000 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5000; }
    { const char * tb_v5001 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5001; }
    { const char * tb_v5002 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v5002; }
    { const char * tb_v5003 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v5003; }
    { const char * tb_v5004 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5004; }
    { const char * tb_v5005 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5005; }
    { const char * tb_v5006 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v5006; }
    { const char * tb_v5007 = "    return !tb_gclosed;\n"; *(const char * *)tb_grow(v_lines) = tb_v5007; }
    { const char * tb_v5008 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5008; }
